def count_coprime_row_choices(mat):
    from math import gcd
    mod=10**9+7;states={0:1}
    for row in mat:
        updated={}
        for common,ways in states.items():
            for value in row:
                key=gcd(common,value);updated[key]=(updated.get(key,0)+ways)%mod
        states=updated
    return states.get(1,0)

